// JSON messages exchanged with the Go server. They mirror internal/api/types.go;
// contract.test.ts checks both sides against contract.json, generated by the Go tests.

export type Side = "a" | "b";

export interface PairView {
  id: number;
  wordA: string;
  wordB: string;
  extreme: boolean;
}

export interface DrawResponse {
  id: number;
  civilWord: string;
  undercoverWord: string;
  civilSide: Side;
  extreme: boolean;
}

export interface GuessRequest {
  civilSide: Side;
  guess: string;
}

export interface GuessResponse {
  correct: boolean;
  expected: string;
}

export type CheckStatus = "ok" | "similar" | "duplicate" | "invalid";

export interface CheckResponse {
  status: CheckStatus;
  error?: string;
  duplicate?: PairView;
  similar: PairView[];
  related: PairView[];
}

export interface CreatePairRequest {
  wordA: string;
  wordB: string;
  extreme: boolean;
  confirmSimilar: boolean;
  /** Honeypot: always empty for humans. */
  website: string;
}

export interface CreatePairResponse {
  pair: PairView;
}

export type ReportReason = "extreme" | "remove";

export interface ReportRequest {
  reason: ReportReason;
}

export interface ErrorResponse {
  error: string;
}

/** One example of every message, as in contract.json. */
export interface Contract {
  pairView: PairView;
  drawResponse: DrawResponse;
  guessRequest: GuessRequest;
  guessResponse: GuessResponse;
  checkResponse: CheckResponse;
  createPairRequest: CreatePairRequest;
  createPairResponse: CreatePairResponse;
  reportRequest: ReportRequest;
  errorResponse: ErrorResponse;
}
